-- Blog enquiry leads: one row per submission of the enquiry form shown under
-- every published blog post. Rows are only ever created through
-- submit_blog_lead() and only ever read by admins (see 0007).

create type blog_lead_status as enum ('new', 'contacted', 'converted', 'closed');

create table blog_leads (
  id uuid primary key default gen_random_uuid(),
  -- Generated by the browser once per form session. A double-click, a retried
  -- request or a replayed Server Action therefore inserts exactly one row.
  submission_key uuid not null unique default gen_random_uuid(),
  name text not null,
  -- Always E.164 ("+919876543210"): one canonical form to search, dial (tel:)
  -- and message (wa.me) from. The form accepts friendlier input and normalises it.
  mobile text not null,
  city text not null,
  -- Lower-cased copy so "Nagpur", "nagpur" and " NAGPUR " filter as one city.
  city_key text generated always as (lower(btrim(city))) stored,
  -- Catalogue id ("<category>/<product>", see src/lib/blog/leads/products.ts)
  -- plus the name/category as they were when the lead came in.
  product_id text not null,
  product_name text not null,
  product_category text,
  -- The post that produced the lead. The slug/title/url snapshot keeps the
  -- record meaningful after the post is renamed, and the lead itself survives
  -- the post being deleted.
  blog_post_id uuid references posts (id) on delete set null,
  blog_slug text not null,
  blog_title text not null,
  blog_url text not null,
  status blog_lead_status not null default 'new',
  status_changed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- Backstops for the validation in submit_blog_lead() and the app.
  constraint blog_leads_name_length check (char_length(name) between 2 and 80),
  constraint blog_leads_city_length check (char_length(city) between 2 and 60),
  constraint blog_leads_mobile_e164 check (mobile ~ '^\+[1-9][0-9]{7,14}$'),
  constraint blog_leads_mobile_india check (mobile !~ '^\+91' or mobile ~ '^\+91[6-9][0-9]{9}$'),
  constraint blog_leads_product_length check (
    char_length(product_id) between 1 and 80
    and char_length(product_name) between 1 and 120
  ),
  constraint blog_leads_blog_length check (
    char_length(blog_slug) between 1 and 200
    and char_length(blog_title) between 1 and 300
    and char_length(blog_url) between 1 and 500
  )
);

-- Locked from the moment it exists. Supabase's default privileges would otherwise hand a new
-- table to anon/authenticated, and this one holds customers' phone numbers — so even if only
-- this file is ever run, nobody can read it. 0007 adds the admin policies/grants on top.
alter table blog_leads enable row level security;
revoke all on table blog_leads from public, anon, authenticated;

create index blog_leads_created_at_idx on blog_leads (created_at desc);
create index blog_leads_status_created_at_idx on blog_leads (status, created_at desc);
create index blog_leads_blog_post_id_idx on blog_leads (blog_post_id, created_at desc);
create index blog_leads_city_key_idx on blog_leads (city_key);
create index blog_leads_product_id_idx on blog_leads (product_id);
-- Per-number duplicate and rate-limit checks in submit_blog_lead().
create index blog_leads_mobile_created_at_idx on blog_leads (mobile, created_at desc);

-- Keeps updated_at current and stamps status_changed_at when the status moves.
create function set_blog_leads_timestamps()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  if new.status is distinct from old.status then
    new.status_changed_at := now();
  end if;
  return new;
end;
$$;

create trigger blog_leads_set_timestamps
  before update on blog_leads
  for each row
  execute function set_blog_leads_timestamps();
